    [6205] = { en = "Physical damage caused by the target is reduced by $s1 for $d. Only one Curse per Warlock can be active on any one target.", description = "Riduce di $s1 i danni fisici inflitti dal bersaglio per $d. Ogni stregone può mantenere una sola Maledizione attiva sullo stesso bersaglio." },
    [6213] = { en = "Strikes fear in the enemy, causing it to run in fear for up to $d.  Damage caused may interrupt the effect.  Only 1 target can be feared at a time.", description = "Incute paura nel nemico, costringendolo a fuggire terrorizzato per un massimo di $d. I danni inflitti possono interrompere l’effetto. Si può impaurire un solo bersaglio alla volta." },
    [6215] = { en = "Strikes fear in the enemy, causing it to run in fear for up to $d.  Damage caused may interrupt the effect.  Only 1 target can be feared at a time.", description = "Incute paura nel nemico, costringendolo a fuggire terrorizzato per un massimo di $d. I danni inflitti possono interrompere l’effetto. Si può impaurire un solo bersaglio alla volta." },
    [6217] = { en = "Afflicts the target with agony, causing $o1 Shadow damage over $d. This damage is dealt slowly at first, and builds up as the Bane reaches its full duration. Only one Bane per Warlock can be active on any one target.", description = "Affligge il bersaglio con agonia, infliggendo $o1 danni da ombra nell’arco di $d. I danni aumentano gradualmente fino alla fine dell’effetto. Ogni Stregone può avere una sola Agonia attiva per bersaglio." },
    [6226] = { en = "Transfers $s1 Mana every $t1 sec from the target to the caster. Lasts $d.", description = "Trasferisce $s1 mana dal bersaglio all’incantatore ogni $t1 sec. Dura $d." },
    [6262] = { en = "Instantly restores $s1 life.", description = "Ripristina istantaneamente $s1 salute." },
    [6263] = { en = "Instantly restores $s1 life.", description = "Ripristina istantaneamente $s1 salute." },
    [6552] = { en = "Pummel the target for $s1 damage.  It also interrupts spellcasting and prevents any spell in that school from being cast for $d.", description = "Colpisce il bersaglio per $s1 danni. Interrompe inoltre il lancio degli incantesimi e impedisce di lanciare incantesimi di quella scuola per $d." },
    [6574] = { en = "Instantly counterattack an enemy for $s1 damage and a high amount of threat.   Revenge must follow a block, dodge or parry.", description = "Contrattacca istantaneamente un nemico, infliggendo $s1 danni e generando molta minaccia.   Revenge può essere usata solo dopo un blocco, una schivata o una parata." },
    [6673] = { en = "The warrior shouts, increasing the melee attack power of all party members within $a1 yards by $s1.  Lasts $d.", description = "Il guerriero grida; tutti i membri del gruppo entro $a1 metri ottengono un aumento di $s1 alla potenza d'attacco in mischia.  Dura $d." },
    [6756] = { en = "Increases the friendly target's armor by $s1 and all attributes by $s2 for $d.", description = "Aumenta di $s1 l'armatura e di $s2 tutti gli attributi del bersaglio amico per $d." },
    [6780] = { en = "Causes $s1 Nature damage to the target.", description = "Infligge $s1 danni da natura al bersaglio." },
    [6808] = { en = "Increases the druid's next attack by $s1 damage.", description = "Aumenta di $s1 i danni del prossimo attacco del druido." },
    [6809] = { en = "Increases the druid's next attack by $s1 damage.", description = "Aumenta di $s1 i danni del prossimo attacco del druido." },
    [6979] = { en = "Fires a flaming shot at the enemy, doing an additional $s1 and making the damage fire based.", description = "Scaglia un colpo infuocato contro il nemico, infliggendo $s1 danni aggiuntivi e convertendo il danno in danno da fuoco." },
    [6980] = { en = "Fires a flaming shot at the enemy, doing an additional $s1 and making the damage fire based.", description = "Scaglia un colpo infuocato contro il nemico, infliggendo $s1 danni aggiuntivi e convertendo il danno in danno da fuoco." },
    [6985] = { en = "Fires a frost shot at the enemy, causing $s1 additional frost damage and slowing the enemy's movement speed by $s2%.", description = "Scaglia un dardo di gelo contro il nemico, infliggendo $s1 danni da gelo aggiuntivi e riducendone la velocità di movimento del $s2%." },
    [7128] = { en = "A burst of Holy energy fills the caster, increasing armor by $s1.  Each melee or ranged damage hit against the priest will remove one charge.  Lasts $d or until $n charges are used.", description = "Un'esplosione di energia sacra avvolge l'incantatore e ne aumenta l'armatura di $s1. Ogni colpo in mischia o a distanza rimuove una carica. Dura $d o fino all'esaurimento di $n cariche." },
