    [7300] = { en = "Increases Armor by $s1.  If an enemy strikes the caster, they may have their movement slowed by $6136s1% and the time between their attacks increased by $6136s2% for $6136d.  Only one type of Armor spell can be active on the Mage at any time.  Lasts $d.", description = "Aumenta l'armatura di $s1. Se un nemico colpisce l'incantatore, può subirne un rallentamento del movimento del $6136s1% e un aumento del tempo tra gli attacchi del $6136s2% per $6136d. Sul mago può essere attivo un solo incantesimo di armatura alla volta. Dura $d." },
    [7301] = { en = "Increases Armor by $s1.  If an enemy strikes the caster, they may have their movement slowed by $6136s1% and the time between their attacks increased by $6136s2% for $6136d.  Only one type of Armor spell can be active on the Mage at any time.  Lasts $d.", description = "Aumenta l'armatura di $s1. Se un nemico colpisce l'incantatore, può subirne un rallentamento del movimento del $6136s1% e un aumento del tempo tra gli attacchi del $6136s2% per $6136d. Sul mago può essere attivo un solo incantesimo di armatura alla volta. Dura $d." },
    [7320] = { en = "Increases Armor by $s1 and frost resistance by $s3.   If an enemy strikes the caster, they may have their movement slowed by $7321s1% and the time between their attacks increased by $7321s2% for $7321d.  Only one type of Armor spell can be active on the Mage at any time.  Lasts $d.", description = "Aumenta l’armatura di $s1 e la resistenza al gelo di $s3. Se un nemico colpisce l’incantatore, il suo movimento può essere rallentato del $7321s1% e il tempo tra i suoi attacchi aumentato del $7321s2% per $7321d. Sul mago può essere attivo un solo incantesimo di armatura alla volta. Dura $d." },
    [7322] = { en = "Launches a bolt of frost at the enemy, causing ${$m2$*$<frostdamage>} to ${$M2*$<frostdamage>}  Frost damage and slowing movement speed by $s1% for $d.", description = "Scaglia un dardo di gelo contro il nemico, infliggendo da ${$m2$*$<frostdamage>} a ${$M2*$<frostdamage>} danni da gelo e riducendone la velocità di movimento del $s1% per $d." },
    [7328] = { en = "Brings a dead player back to life with $s1 health and $q1 mana.  Cannot be cast when in combat.", description = "Riporta in vita un giocatore morto con $s1 salute e $q1 mana. Non si può lanciare in combattimento." },
    [7369] = { en = "A sweeping attack that does your weapon damage plus $s1 to the target and a second nearby enemy.", description = "Attacca con un ampio fendente, infliggendo al bersaglio e a un secondo nemico vicino i danni dell'arma più $s1." },
    [7379] = { en = "Instantly counterattack an enemy for $s1 damage and a high amount of threat.   Revenge must follow a block, dodge or parry.", description = "Contrattacca istantaneamente un nemico, infliggendo $s1 danni e generando molta minaccia.   Revenge può essere usata solo dopo un blocco, una schivata o una parata." },
    [7384] = { en = "Instantly overpower the enemy, causing weapon damage plus $s1.  Only useable after the target dodges.  The Overpower cannot be blocked, dodged or parried.", description = "Sopraffà istantaneamente il nemico, infliggendo i danni dell’arma più $s1. Usabile solo dopo che il bersaglio ha schivato. Sopraffazione non può essere bloccata, schivata o parata." },
    [7386] = { en = "Sunders the target's armor, reducing it by $s1 per Sunder Armor and causes a high amount of threat.  Can be applied up to 5 times.  Lasts $d.", description = "Frantuma l’armatura del bersaglio, riducendola di $s1 per ogni applicazione di Sunder Armor e generando molta minaccia. Può accumularsi fino a 5 volte. Dura $d." },
    [7396] = { en = "Increases your attack speed by $s1% for $d.", description = "Aumenta la velocità d’attacco del $s1% per $d." },
    [7400] = { en = "A mocking attack that causes $s1 damage, a moderate amount of threat and forces the target to focus attacks on you for $d.", description = "Un attacco provocatorio che infligge $s1 danni, genera una quantità moderata di minaccia e costringe il bersaglio a concentrarsi su di te per $d." },
