    [8131] = { en = "Drains $s1 mana from a target. For each mana drained in this way, the target takes 0.5 Shadow damage.", description = "Sottrae $s1 mana al bersaglio. Per ogni punto mana sottratto in questo modo, il bersaglio subisce 0,5 danni da ombra." },
    [8143] = { en = "Summons a Tremor Totem with $s1 health at the feet of the caster that shakes the ground around it, removing Fear, Charm and Sleep effects from party members within $8146a1 yards.  Lasts $d.", description = "Evoca ai piedi dell’incantatore un Totem del Tremore con $s1 salute. Il totem scuote il terreno circostante e rimuove gli effetti di Paura, Ammaliamento e Sonno dai membri del gruppo entro $8146a1 m. Dura $d." },
    [8192] = { en = "Soothes the target, reducing the range at which it will attack you by $s1 yards.  Only affects Humanoid targets level $v or lower.  Lasts $d.", description = "Placa il bersaglio, riducendo di $s1 iarde la distanza alla quale può attaccarti. Funziona solo sugli Umanoidi di livello $v o inferiore. Dura $d." },
    [8205] = { en = "Blasts nearby enemies with thunder, increasing the time between their attacks by $s2% for $d and doing $s1 damage to them. Will affect up to $i targets.", description = "Colpisce i nemici vicini con un tuono, aumentando del $s2% il tempo tra i loro attacchi per $d e infliggendo loro $s1 danni. Può colpire fino a $i bersagli." },
    [8257] = { en = "Inflicts $s2 Nature damage to an enemy, then an additional $s1 damage every $t1 sec. for $d.", description = "Infligge $s2 danni da natura a un nemico, poi altri $s1 danni ogni $t1 s per $d." },
    [8288] = { en = "Drains the soul of the target, causing $o2 Shadow damage over $d. Non-trivial targets damaged by Drain Soul have a chance to grant you a Soul Shard. Non-trivial targets killed by Drain Soul will always grant you a Soul shard. Soul Shards are required for other spells.", description = "Risucchia l’anima del bersaglio, infliggendo $o2 danni da ombra in $d. I bersagli impegnativi danneggiati da Risucchio dell’Anima possono fornirti un Frammento d’Anima. I bersagli impegnativi uccisi da Risucchio dell’Anima ne forniscono sempre uno. I Frammenti d’Anima servono per altri incantesimi." },
    [8289] = { en = "Drains the soul of the target, causing $o2 Shadow damage over $d. Non-trivial targets damaged by Drain Soul have a chance to grant you a Soul Shard. Non-trivial targets killed by Drain Soul will always grant you a Soul shard. Soul Shards are required for other spells.", description = "Risucchia l’anima del bersaglio, infliggendo $o2 danni da ombra in $d. I bersagli impegnativi danneggiati da Risucchio dell’Anima possono fornirti un Frammento d’Anima. I bersagli impegnativi uccisi da Risucchio dell’Anima ne forniscono sempre uno. I Frammenti d’Anima servono per altri incantesimi." },
    [8316] = { en = "Surrounds the target in a shield of fire.  Every strike against the target causes $s1 Fire damage to the attacker.  Lasts $d.  Your pet cannot cast Fire Shield on itself.", description = "Avvolge il bersaglio in uno scudo di fuoco. Ogni attacco contro il bersaglio infligge $s1 danni da fuoco all’attaccante. Dura $d. Il tuo famiglio non può lanciare Scudo di Fuoco su se stesso." },
    [8317] = { en = "Surrounds the target in a shield of fire.  Every strike against the target causes $s1 Fire damage to the attacker.  Lasts $d.  Your pet cannot cast Fire Shield on itself.", description = "Avvolge il bersaglio in uno scudo di fuoco. Ogni attacco contro il bersaglio infligge $s1 danni da fuoco all’attaccante. Dura $d. Il tuo famiglio non può lanciare Scudo di Fuoco su se stesso." },
    [8380] = { en = "Sunders the target's armor, reducing it by $s1 per Sunder Armor and causes a high amount of threat.  Can be applied up to 5 times.  Lasts $d.", description = "Frantuma l’armatura del bersaglio, riducendola di $s1 per ogni applicazione di Sunder Armor e generando molta minaccia. Può accumularsi fino a 5 volte. Dura $d." },
    [8387] = { en = "Nearby herb bushes appear on the minimap.   Only one type of thing can be tracked at a time.", description = "Mostra sulla minimappa i cespugli di erbe nelle vicinanze. È possibile tenere attivo un solo tipo di tracciamento alla volta." },
    [8388] = { en = "Nearby mineral veins appear on the minimap.   Only one type of thing can be tracked at a time.", description = "Mostra sulla minimappa i filoni di minerali nelle vicinanze. È possibile tenere attivo un solo tipo di tracciamento alla volta." },
    [8395] = { en = "Summons and dismisses a rideable Raptor.", description = "Evoca e congeda un raptor cavalcabile." },
    [8400] = { en = "Hurls a fiery ball that causes $s1 Fire damage and an additional $o2 Fire damage over $d.", description = "Scaglia una palla di fuoco che infligge $s1 danni da fuoco e altri $o2 danni da fuoco in $d." },
    [8401] = { en = "Hurls a fiery ball that causes $s1 Fire damage and an additional $o2 Fire damage over $d.", description = "Scaglia una palla di fuoco che infligge $s1 danni da fuoco e altri $o2 danni da fuoco in $d." },
    [8402] = { en = "Hurls a fiery ball that causes $s1 Fire damage and an additional $o2 Fire damage over $d.", description = "Scaglia una palla di fuoco che infligge $s1 danni da fuoco e altri $o2 danni da fuoco in $d." },
    [8406] = { en = "Launches a bolt of frost at the enemy, causing ${$m2$*$<frostdamage>} to ${$M2*$<frostdamage>}  Frost damage and slowing movement speed by $s1% for $d.", description = "Scaglia un dardo di gelo contro il nemico, infliggendo da ${$m2$*$<frostdamage>} a ${$M2*$<frostdamage>} danni da gelo e riducendone la velocità di movimento del $s1% per $d." },
    [8407] = { en = "Launches a bolt of frost at the enemy, causing ${$m2$*$<frostdamage>} to ${$M2*$<frostdamage>}  Frost damage and slowing movement speed by $s1% for $d.", description = "Scaglia un dardo di gelo contro il nemico, infliggendo da ${$m2$*$<frostdamage>} a ${$M2*$<frostdamage>} danni da gelo e riducendone la velocità di movimento del $s1% per $d." },
    [8408] = { en = "Launches a bolt of frost at the enemy, causing ${$m2$*$<frostdamage>} to ${$M2*$<frostdamage>}  Frost damage and slowing movement speed by $s1% for $d.", description = "Scaglia un dardo di gelo contro il nemico, infliggendo da ${$m2$*$<frostdamage>} a ${$M2*$<frostdamage>} danni da gelo e riducendone la velocità di movimento del $s1% per $d." },
    [8450] = { en = "Dampens magic used against the targeted party member, decreasing damage taken from spells by up to $s1 and healing spells by up to $s2.  Lasts $d.", description = "Attenua la magia diretta contro il membro del gruppo selezionato, riducendo fino a $s1 i danni subiti dagli incantesimi e fino a $s2 le cure ricevute. Dura $d." },
    [8451] = { en = "Dampens magic used against the targeted party member, decreasing damage taken from spells by up to $s1 and healing spells by up to $s2.  Lasts $d.", description = "Attenua la magia diretta contro il membro del gruppo selezionato, riducendo fino a $s1 i danni subiti dagli incantesimi e fino a $s2 le cure ricevute. Dura $d." },
    [8455] = { en = "Amplifies magic used against the targeted party member, increasing damage taken from spells by up to $s1 and healing spells by up to $s2.  Lasts $d.", description = "Amplifica la magia usata contro il membro del gruppo selezionato, aumentando fino a $s1 i danni subiti dagli incantesimi e fino a $s2 le cure ricevute. Dura $d." },
    [8494] = { en = "Absorbs $s1 physical damage, draining mana instead.  Drains $e mana per damage absorbed.  Lasts $d.", description = "Assorbe $s1 danni fisici, consumando mana al loro posto.  Consuma $e mana per ogni danno assorbito.  Dura $d." },
    [8495] = { en = "Absorbs $s1 physical damage, draining mana instead.  Drains $e mana per damage absorbed.  Lasts $d.", description = "Assorbe $s1 danni fisici, consumando mana al loro posto.  Consuma $e mana per ogni danno assorbito.  Dura $d." },
    [8621] = { en = "An instant strike that causes $s1 damage in addition to your normal weapon damage.  Awards $s2 combo $lpoint:points;.", description = "Un colpo istantaneo che infligge $s1 danni aggiuntivi rispetto ai normali danni dell'arma. Genera $s2 $lpoint:punti; combo." },
    [8637] = { en = "Performs a feint, causing no damage but lowering your threat by a large amount, making the enemy less likely to attack you.", description = "Esegue una finta senza infliggere danni, ma riduce notevolmente la tua minaccia e rende il nemico meno incline ad attaccarti." },
    [8640] = { en = "Finishing move that causes damage over time, increased by your Attack Power.  Lasts longer per combo point:\r\n   1 point  : ${($m1+$b1)*4} damage over 8 secs\r\n   2 points: ${($m1+$b1*2)*5} damage over 10 secs\r\n   3 points: ${($m1+$b1*3)*6} damage over 12 secs\r\n   4 points: ${($m1+$b1*4)*7} damage over 14 secs\r\n   5 points: ${($m1+$b1*5)*8} damage over 16 secs", description = "Mossa finale che infligge danni periodici, aumentati dalla tua potenza d'attacco.  La durata e i danni aumentano per ogni punto combo:\r\n1 punto: ${($m1+$b1)*4} danni in 8 s\r\n2 punti: ${($m1+$b1*2)*5} danni in 10 s\r\n3 punti: ${($m1+$b1*3)*6} danni in 12 s\r\n4 punti: ${($m1+$b1*4)*7} danni in 14 s\r\n5 punti: ${($m1+$b1*5)*8} danni in 16 s" },
    [8649] = { en = "Finishing move that exposes the target for $d, reducing armor per combo point:\r\n   1 point  : ${$b*-1} armor\r\n   2 points: ${$b*-2} armor\r\n   3 points: ${$b*-3} armor\r\n   4 points: ${$b*-4} armor\r\n   5 points: ${$b*-5} armor", description = "Mossa finale che espone il bersaglio per $d, riducendone l'armatura in base ai punti combo:\n   1 punto: ${$b*-1} armatura\n   2 punti: ${$b*-2} armatura\n   3 punti: ${$b*-3} armatura\n   4 punti: ${$b*-4} armatura\n   5 punti: ${$b*-5} armatura" },
    [8650] = { en = "Finishing move that exposes the target for $d, reducing armor per combo point:\r\n   1 point  : ${$b*-1} armor\r\n   2 points: ${$b*-2} armor\r\n   3 points: ${$b*-3} armor\r\n   4 points: ${$b*-4} armor\r\n   5 points: ${$b*-5} armor", description = "Mossa finale che espone il bersaglio per $d, riducendone l'armatura in base ai punti combo:\n   1 punto: ${$b*-1} armatura\n   2 punti: ${$b*-2} armatura\n   3 punti: ${$b*-3} armatura\n   4 punti: ${$b*-4} armatura\n   5 punti: ${$b*-5} armatura" },
