    [10169] = { en = "Amplifies magic used against the targeted party member, increasing damage taken from spells by up to $s1 and healing spells by up to $s2.  Lasts $d.", description = "Amplifica la magia usata contro il membro del gruppo selezionato, aumentando fino a $s1 i danni subiti dagli incantesimi e fino a $s2 le cure ricevute. Dura $d." },
