    [10179] = { en = "Launches a bolt of frost at the enemy, causing ${$m2$*$<frostdamage>} to ${$M2*$<frostdamage>}  Frost damage and slowing movement speed by $s1% for $d.", description = "Scaglia un dardo di gelo contro il nemico, infliggendo da ${$m2$*$<frostdamage>} a ${$M2*$<frostdamage>} danni da gelo e riducendone la velocità di movimento del $s1% per $d." },
