    [10191] = { en = "Absorbs $s1 physical damage, draining mana instead.  Drains $e mana per damage absorbed.  Lasts $d.", description = "Assorbe $s1 danni fisici, consumando mana al loro posto.  Consuma $e mana per ogni danno assorbito.  Dura $d." },
    [10192] = { en = "Absorbs $s1 physical damage, draining mana instead.  Drains $e mana per damage absorbed.  Lasts $d.", description = "Assorbe $s1 danni fisici, consumando mana al loro posto.  Consuma $e mana per ogni danno assorbito.  Dura $d." },
    [10193] = { en = "Absorbs $s1 physical damage, draining mana instead.  Drains $e mana per damage absorbed.  Lasts $d.", description = "Assorbe $s1 danni fisici, consumando mana al loro posto.  Consuma $e mana per ogni danno assorbito.  Dura $d." },
    [10219] = { en = "Increases Armor by $s1 and frost resistance by $s3.   If an enemy strikes the caster, they may have their movement slowed by $7321s1% and the time between their attacks increased by $7321s2% for $7321d.  Only one type of Armor spell can be active on the Mage at any time.  Lasts $d.", description = "Aumenta l’armatura di $s1 e la resistenza al gelo di $s3. Se un nemico colpisce l’incantatore, il suo movimento può essere rallentato del $7321s1% e il tempo tra i suoi attacchi aumentato del $7321s2% per $7321d. Sul mago può essere attivo un solo incantesimo di armatura alla volta. Dura $d." },
    [10220] = { en = "Increases Armor by $s1 and frost resistance by $s3.   If an enemy strikes the caster, they may have their movement slowed by $7321s1% and the time between their attacks increased by $7321s2% for $7321d.  Only one type of Armor spell can be active on the Mage at any time.  Lasts $d.", description = "Aumenta l’armatura di $s1 e la resistenza al gelo di $s3. Se un nemico colpisce l’incantatore, il suo movimento può essere rallentato del $7321s1% e il tempo tra i suoi attacchi aumentato del $7321s2% per $7321d. Sul mago può essere attivo un solo incantesimo di armatura alla volta. Dura $d." },
    [10230] = { en = "Blasts enemies near the caster for ${$m1*$<frostdamage>} to ${$M1*$<frostdamage>} Frost damage and freezes them in place for up to $d.  Damage caused may interrupt the effect.", description = "Colpisce i nemici vicini all'incantatore, infliggendo da ${$m1*$<frostdamage>} a ${$M1*$<frostdamage>} danni da gelo e congelandoli sul posto per un massimo di $d. I danni inflitti possono interrompere l'effetto." },
    [10242] = { en = "Shows the location of all nearby elementals on the minimap for $d.", description = "Mostra sulla minimappa la posizione di tutti gli elementali vicini per $d." },
    [10278] = { en = "A targeted party member is protected from all physical attacks for $d, but during that time they cannot attack or use physical abilities.  Players may only have one Blessing on them per Paladin at any one time.  Applies Forbearance for $25771d. Cannot be cast while Forbearance is active.", description = "Protegge un membro del gruppo dagli attacchi fisici per $d, ma per tutta la durata gli impedisce di attaccare o usare abilità fisiche.  Ogni paladino può avere attiva su un giocatore una sola Benedizione alla volta.  Applica Resa dei Conti per $25771d. Non può essere lanciato mentre Resa dei Conti è attiva." },
    [10290] = { en = "Gives $s1 additional armor to party members within $a1 yards.  Players may only have one Aura on them per Paladin at any one time.", description = "Fornisce $s1 armatura aggiuntiva ai membri del gruppo entro $a1 m. Ogni paladino può applicare una sola Aura a ciascun giocatore." },
    [10291] = { en = "Gives $s1 additional armor to party members within $a1 yards.  Players may only have one Aura on them per Paladin at any one time.", description = "Fornisce $s1 armatura aggiuntiva ai membri del gruppo entro $a1 m. Ogni paladino può applicare una sola Aura a ciascun giocatore." },
