    [10951] = { en = "A burst of Holy energy fills the caster, increasing armor by $s1.  Each melee or ranged damage hit against the priest will remove one charge.  Lasts $d or until $n charges are used.", description = "Un'esplosione di energia sacra avvolge l'incantatore e ne aumenta l'armatura di $s1. Ogni colpo in mischia o a distanza rimuove una carica. Dura $d o fino all'esaurimento di $n cariche." },
