    [10953] = { en = "Soothes the target, reducing the range at which it will attack you by $s1 yards.  Only affects Humanoid targets level $v or lower.  Lasts $d.", description = "Placa il bersaglio, riducendo di $s1 iarde la distanza alla quale può attaccarti. Funziona solo sugli Umanoidi di livello $v o inferiore. Dura $d." },
    [10960] = { en = "A powerful prayer that heals the target and their party for $s1. Party members must be within $a1 yards of target.", description = "Una preghiera potente cura il bersaglio e i membri del suo gruppo di $s1. I membri del gruppo devono trovarsi entro $a1 metri dal bersaglio." },
