    [11665] = { en = "Burns the enemy for ${$m2*$<mult>} Fire damage and then an additional $o1 Fire damage over $d.", description = "Brucia il nemico infliggendo ${$m2*$<mult>} danni da fuoco, poi infligge altri $o1 danni da fuoco in $d." },
