    [11675] = { en = "Drains the soul of the target, causing $o2 Shadow damage over $d. Non-trivial targets damaged by Drain Soul have a chance to grant you a Soul Shard. Non-trivial targets killed by Drain Soul will always grant you a Soul shard. Soul Shards are required for other spells.", description = "Risucchia l’anima del bersaglio, infliggendo $o2 danni da ombra in $d. I bersagli impegnativi danneggiati da Risucchio dell’Anima possono fornirti un Frammento d’Anima. I bersagli impegnativi uccisi da Risucchio dell’Anima ne forniscono sempre uno. I Frammenti d’Anima servono per altri incantesimi." },
