    [11699] = { en = "Transfers $s1 health every $t1 second from the target to the caster. Lasts $d.\r\n", description = "Trasferisce $s1 salute dal bersaglio all'incantatore ogni $t1 s. Dura $d.\r\n            " },
    [11700] = { en = "Transfers $s1 health every $t1 second from the target to the caster. Lasts $d.", description = "Trasferisce $s1 punti salute dal bersaglio all'incantatore ogni $t1 s. Dura $d." },
    [11703] = { en = "Transfers $s1 Mana every $t1 sec from the target to the caster. Lasts $d.", description = "Trasferisce $s1 mana dal bersaglio all’incantatore ogni $t1 sec. Dura $d." },
