    [11707] = { en = "Physical damage caused by the target is reduced by $s1 for $d. Only one Curse per Warlock can be active on any one target.", description = "Riduce di $s1 i danni fisici inflitti dal bersaglio per $d. Ogni stregone può mantenere una sola Maledizione attiva sullo stesso bersaglio." },
    [11708] = { en = "Physical damage caused by the target is reduced by $s1 for $d. Only one Curse per Warlock can be active on any one target.", description = "Riduce di $s1 i danni fisici inflitti dal bersaglio per $d. Ogni stregone può mantenere una sola Maledizione attiva sullo stesso bersaglio." },
    [11711] = { en = "Afflicts the target with agony, causing $o1 Shadow damage over $d. This damage is dealt slowly at first, and builds up as the Bane reaches its full duration. Only one Bane per Warlock can be active on any one target.", description = "Affligge il bersaglio con agonia, infliggendo $o1 danni da ombra nell’arco di $d. I danni aumentano gradualmente fino alla fine dell’effetto. Ogni Stregone può avere una sola Agonia attiva per bersaglio." },
    [11712] = { en = "Afflicts the target with agony, causing $o1 Shadow damage over $d. This damage is dealt slowly at first, and builds up as the Bane reaches its full duration. Only one Bane per Warlock can be active on any one target.", description = "Affligge il bersaglio con agonia, infliggendo $o1 danni da ombra nell’arco di $d. I danni aumentano gradualmente fino alla fine dell’effetto. Ogni Stregone può avere una sola Agonia attiva per bersaglio." },
    [11713] = { en = "Afflicts the target with agony, causing $o1 Shadow damage over $d. This damage is dealt slowly at first, and builds up as the Bane reaches its full duration. Only one Bane per Warlock can be active on any one target.", description = "Affligge il bersaglio con agonia, infliggendo $o1 danni da ombra nell’arco di $d. I danni aumentano gradualmente fino alla fine dell’effetto. Ogni Stregone può avere una sola Agonia attiva per bersaglio." },
    [11717] = { en = "Curses the target with recklessness, reducing the target's armor by $s2 for $d. Cursed enemies will not flee and will ignore Fear and Horror effects. Only one Curse per Warlock can be active on any one target.", description = "Maledice il bersaglio, riducendone l'armatura di $s2 per $d. I nemici maledetti non fuggono e ignorano gli effetti di Paura e Terrore. Ogni stregone può mantenere una sola Maledizione attiva sullo stesso bersaglio." },
    [11719] = { en = "Forces the target to speak in Demonic, increasing the casting time of all spells by $s1%. Only one Curse per Warlock can be active on any one target. Lasts $d.", description = "Costringe il bersaglio a parlare in Demoniaco, aumentando del $s1% il tempo di lancio di tutti gli incantesimi. Un warlock può avere attiva una sola Maledizione su ciascun bersaglio. Dura $d." },
    [11725] = { en = "Subjugates the target demon, up to level $m1, forcing it to do your bidding.  While subjugated, the time between the demon's attacks is increased by $s2% and its casting speed is slowed by $s3%.  Lasts up to $d.  If you repeatedly subjugate the same demon, it will become more difficult to control with each attempt.", description = "Soggioga il demone bersaglio fino al livello $m1 e lo costringe a eseguire i tuoi ordini. Mentre è soggiogato, il tempo tra i suoi attacchi aumenta del $s2% e la sua velocità di lancio degli incantesimi si riduce del $s3%. Dura fino a $d. Se soggioghi ripetutamente lo stesso demone, ogni tentativo rende più difficile controllarlo." },
    [11726] = { en = "Subjugates the target demon, up to level $m1, forcing it to do your bidding.  While subjugated, the time between the demon's attacks is increased by $s2% and its casting speed is slowed by $s3%.  Lasts up to $d.  If you repeatedly subjugate the same demon, it will become more difficult to control with each attempt.", description = "Soggioga il demone bersaglio fino al livello $m1 e lo costringe a eseguire i tuoi ordini. Mentre è soggiogato, il tempo tra i suoi attacchi aumenta del $s2% e la sua velocità di lancio degli incantesimi si riduce del $s3%. Dura fino a $d. Se soggioghi ripetutamente lo stesso demone, ogni tentativo rende più difficile controllarlo." },
    [11732] = { en = "Instantly restores $s1 life.", description = "Ripristina istantaneamente $s1 salute." },
    [11733] = { en = "Protects the caster, increasing armor by $s1, Shadow resistance by $s2 and increases health regeneration by $s3 health per 5 sec. for $d.", description = "Protegge l'incantatore, aumentandone l'armatura di $s1, la resistenza all'ombra di $s2 e la rigenerazione della salute di $s3 ogni 5 s per $d." },
    [11734] = { en = "Protects the caster, increasing armor by $s1, Shadow resistance by $s2 and increases health regeneration by $s3 health per 5 sec. for $d.", description = "Protegge l'incantatore, aumentandone l'armatura di $s1, la resistenza all'ombra di $s2 e la rigenerazione della salute di $s3 ogni 5 s per $d." },
    [11735] = { en = "Protects the caster, increasing armor by $s1, Shadow resistance by $s2 and increases health regeneration by $s3 health per 5 sec. for $d.", description = "Protegge l'incantatore, aumentandone l'armatura di $s1, la resistenza all'ombra di $s2 e la rigenerazione della salute di $s3 ogni 5 s per $d." },
    [11766] = { en = "Increases party members' Stamina by $s1.", description = "Aumenta di $s1 la Tempra dei membri del gruppo." },
