    [11770] = { en = "Surrounds the target in a shield of fire.  Every strike against the target causes $s1 Fire damage to the attacker.  Lasts $d.  Your pet cannot cast Fire Shield on itself.", description = "Avvolge il bersaglio in uno scudo di fuoco. Ogni attacco contro il bersaglio infligge $s1 danni da fuoco all’attaccante. Dura $d. Il tuo famiglio non può lanciare Scudo di Fuoco su se stesso." },
    [12019] = { en = "Increases damage and healing done by magical spells and effects by up to $s1.", description = "Aumenta fino a $s1 i danni e le cure inflitti dagli incantesimi e dagli effetti magici." },
