    [12543] = { en = "Inflicts $s1 Fire damage and stuns targets in a 3 yard radius for $d. Any damage will break the effect.", description = "Infligge $s1 danni da fuoco e stordisce i bersagli entro un raggio di 3 m per $d. Qualsiasi danno subito interrompe l’effetto." },
    [12565] = { en = "Increases your running speed.   The longer you run the faster you go up to a maximum speed.  You cannot use plainsrunning in combat, underwater, or Indoors.", description = "Aumenta la velocità di corsa. Più a lungo corri, più vai veloce, fino a raggiungere la velocità massima. Non puoi usare la corsa nelle pianure in combattimento, sott’acqua o al chiuso." },
    [12823] = { en = "+$s1 Attack Power against Demons.", description = "+$s1 potenza d’attacco contro i Demoni." },
    [12824] = { en = "Transforms the enemy into a sheep, forcing it to wander around for up to $d.  While wandering, the sheep cannot attack or cast spells but will regenerate very quickly.  Any damage will transform the target back into its normal form.  Only one target can be polymorphed at a time.  Only works on Beasts, Humanoids and Critters.", description = "Trasforma il nemico in una pecora, costringendola a vagare per $d. Mentre vaga, non può attaccare né lanciare incantesimi, ma rigenera salute molto rapidamente. Qualsiasi danno riporta il bersaglio alla sua forma normale. Puoi trasformare un solo bersaglio alla volta. Funziona solo su Bestie, Umanoidi e piccole creature." },
    [12825] = { en = "Transforms the enemy into a sheep, forcing it to wander around for up to $d.  While wandering, the sheep cannot attack or cast spells but will regenerate very quickly.  Any damage will transform the target back into its normal form.  Only one target can be polymorphed at a time.  Only works on Beasts, Humanoids and Critters.", description = "Trasforma il nemico in una pecora, costringendola a vagare per $d. Mentre vaga, non può attaccare né lanciare incantesimi, ma rigenera salute molto rapidamente. Qualsiasi danno riporta il bersaglio alla sua forma normale. Puoi trasformare un solo bersaglio alla volta. Funziona solo su Bestie, Umanoidi e piccole creature." },
    [12826] = { en = "Transforms the enemy into a sheep, forcing it to wander around for up to $d.  While wandering, the sheep cannot attack or cast spells but will regenerate very quickly.  Any damage will transform the target back into its normal form.  Only one target can be polymorphed at a time.  Only works on Beasts, Humanoids and Critters.", description = "Trasforma il nemico in una pecora, costringendola a vagare per $d. Mentre vaga, non può attaccare né lanciare incantesimi, ma rigenera salute molto rapidamente. Qualsiasi danno riporta il bersaglio alla sua forma normale. Puoi trasformare un solo bersaglio alla volta. Funziona solo su Bestie, Umanoidi e piccole creature." },
