    [20560] = { en = "A mocking attack that causes $s1 damage, a moderate amount of threat and forces the target to focus attacks on you for $d.", description = "Un attacco provocatorio che infligge $s1 danni, genera una quantità moderata di minaccia e costringe il bersaglio a concentrarsi su di te per $d." },
