    [20606] = { en = "+$s1 Attack Power against Undead.", description = "+$s1 potenza d’attacco contro i Non Morti." },
    [20609] = { en = "Returns the spirit to the body, restoring a dead target to life with $s1 health and $q1 mana.  Cannot be cast when in combat.", description = "Richiama lo spirito nel corpo e riporta in vita un bersaglio morto con $s1 salute e $q1 mana. Non si può lanciare in combattimento." },
