    [20901] = { en = "An aimed shot that increases ranged damage by $s1. Aimed Shot shares its cooldown with Multi-Shot.", description = "Un tiro mirato che aumenta di $s1 i danni a distanza. Tiro Mirato condivide il tempo di recupero con Tiro Multiplo." },
    [20902] = { en = "An aimed shot that increases ranged damage by $s1. Aimed Shot shares its cooldown with Multi-Shot.", description = "Un tiro mirato che aumenta di $s1 i danni a distanza. Tiro Mirato condivide il tempo di recupero con Tiro Multiplo." },
    [20903] = { en = "An aimed shot that increases ranged damage by $s1. Aimed Shot shares its cooldown with Multi-Shot.", description = "Un tiro mirato che aumenta di $s1 i danni a distanza. Tiro Mirato condivide il tempo di recupero con Tiro Multiplo." },
    [20904] = { en = "An aimed shot that increases ranged damage by $s1. Aimed Shot shares its cooldown with Multi-Shot.", description = "Un tiro mirato che aumenta di $s1 i danni a distanza. Tiro Mirato condivide il tempo di recupero con Tiro Multiplo." },
    [20905] = { en = "Increases the Ranged Attack Power of party members within $a1 yards by $s1. Lasts $d.", description = "Aumenta la potenza d’attacco a distanza dei membri del gruppo entro $a1 metri di $s1. Dura $d." },
    [20906] = { en = "Increases the Ranged Attack Power of party members within $a1 yards by $s1. Lasts $d.", description = "Aumenta la potenza d’attacco a distanza dei membri del gruppo entro $a1 metri di $s1. Dura $d." },
    [20909] = { en = "A strike that becomes active after parrying an opponent's attack. This attack deals $s2% weapon damage plus $m1 and immobilizes the target for $d. Counterattack cannot be blocked, dodged, or parried.", description = "Un contrattacco che si attiva dopo aver parato un attacco avversario. Infligge danni pari al $s2% dei danni dell’arma più $m1 e immobilizza il bersaglio per $d. Non può essere bloccato, schivato o parato." },
    [20910] = { en = "A strike that becomes active after parrying an opponent's attack. This attack deals $s2% weapon damage plus $m1 and immobilizes the target for $d. Counterattack cannot be blocked, dodged, or parried.", description = "Un contrattacco che si attiva dopo aver parato un attacco avversario. Infligge danni pari al $s2% dei danni dell’arma più $m1 e immobilizza il bersaglio per $d. Non può essere bloccato, schivato o parato." },
    [20928] = { en = "Increases chance to block by $s1% for $d, and deals $s2 Holy damage for each attack blocked while active. Damage caused by Holy Shield causes 20% additional threat.", description = "Aumenta del $s1% la probabilità di blocco per $d e infligge $s2 danni sacri per ogni attacco bloccato mentre è attivo. I danni di Scudo Sacro generano il 20% di minaccia aggiuntiva." },
    [20987] = { en = "+$s1 Attack Power.", description = "+$s1 potenza d’attacco." },
    [21007] = { en = "Reduces the Physical damage dealt by nearby enemies by $s1 for $d. Only one curse per warlock can be active on any one target.", description = "Riduce di $s1 i danni fisici inflitti dai nemici vicini per $d. Un warlock può avere attiva una sola maledizione su ciascun bersaglio." },
    [21078] = { en = "DND", description = "Non eliminare." },
