    [25020] = { en = "Surrounds the caster with $n balls of lightning that have $h% chance of striking melee or ranged attackers for $s1 damage. Each time the lightning shield strikes, a ball of lightning dissipates. Thus, the shield expires after $d. or after it has struck $n times.", description = "Circonda l'incantatore con $n sfere di fulmini, ciascuna con una probabilità del $h% di colpire chi attacca in mischia o a distanza, infliggendo $s1 danni. Ogni volta che lo scudo del fulmine colpisce, una sfera si dissolve. Lo scudo termina dopo $d. oppure dopo aver colpito $n volte." },
    [25067] = { en = "Increases healing done by spells and effects by up to $s1 and damage done by up to $s2.", description = "Aumenta fino a $s1 le cure e fino a $s2 i danni inflitti dagli incantesimi e dagli effetti." },
