    [25191] = { en = "Charges an enemy, inflicting normal damage plus $s2 ", description = "Carica un nemico, infliggendo danni normali più $s2." },
    [25286] = { en = "A strong attack that increases melee damage by $s1 and causes a high amount of threat.", description = "Un potente attacco che aumenta i danni in mischia di $s1 e genera molta minaccia." },
    [25288] = { en = "Instantly counterattack an enemy for $s1 damage and a high amount of threat.   Revenge must follow a block, dodge or parry.", description = "Contrattacca istantaneamente un nemico, infliggendo $s1 danni e generando molta minaccia.   Revenge può essere usata solo dopo un blocco, una schivata o una parata." },
    [25289] = { en = "The warrior shouts, increasing the melee attack power of all party members within $a1 yards by $s1.  Lasts $d.", description = "Il guerriero grida; tutti i membri del gruppo entro $a1 metri ottengono un aumento di $s1 alla potenza d'attacco in mischia.  Dura $d." },
    [25290] = { en = "Places a Blessing on the friendly target, restoring $s1 mana every $t1 seconds for $d.  Players may only have one Blessing on them per Paladin at any one time.", description = "Benedice il bersaglio amico, ripristinando $s1 mana ogni $t1 secondi per $d.  Ogni paladino può avere attiva su un giocatore una sola Benedizione alla volta." },
    [25291] = { en = "Places a Blessing on the friendly target, increasing melee attack power by $s1 for $d.  Players may only have one Blessing on them per Paladin at any one time.", description = "Benedice il bersaglio amico, aumentandone la potenza d'attacco in mischia di $s1 per $d.  Ogni paladino può avere attiva su un giocatore una sola Benedizione alla volta." },
    [25295] = { en = "Stings the target, causing $o1 Nature damage over $d.  Only one Sting per Hunter can be active on any one target.", description = "Punge il bersaglio, infliggendo $o1 danni da natura in $d. Un cacciatore può mantenere attiva una sola Puntura su ciascun bersaglio." },
    [25296] = { en = "The hunter takes on the aspects of a hawk, increasing Ranged Attack Power by $s1.  Only one Aspect can be active at a time.", description = "Il cacciatore assume l'Aspetto del Falco, aumentando di $s1 la potenza d'attacco a distanza.  Può essere attivo un solo Aspetto alla volta." },
    [25298] = { en = "Causes $s1 Arcane damage to the target.", description = "Infligge $s1 danni arcani al bersaglio." },
    [25299] = { en = "Heals the target for $o1 over $d.", description = "Cura il bersaglio di $o1 punti salute in $d." },
    [25302] = { en = "Performs a feint, causing no damage but lowering your threat by a large amount, making the enemy less likely to attack you.", description = "Esegue una finta senza infliggere danni, ma riduce notevolmente la tua minaccia e rende il nemico meno incline ad attaccarti." },
    [25304] = { en = "Launches a bolt of frost at the enemy, causing ${$m2$*$<frostdamage>} to ${$M2*$<frostdamage>}  Frost damage and slowing movement speed by $s1% for $d.", description = "Scaglia un dardo di gelo contro il nemico, infliggendo da ${$m2$*$<frostdamage>} a ${$M2*$<frostdamage>} danni da gelo e riducendone la velocità di movimento del $s1% per $d." },
    [25306] = { en = "Hurls a fiery ball that causes $s1 Fire damage and an additional $o2 Fire damage over $d.", description = "Scaglia una palla di fuoco che infligge $s1 danni da fuoco e altri $o2 danni da fuoco in $d." },
    [25309] = { en = "Burns the enemy for ${$m2*$<mult>} Fire damage and then an additional $o1 Fire damage over $d.", description = "Brucia il nemico infliggendo ${$m2*$<mult>} danni da fuoco, poi infligge altri $o1 danni da fuoco in $d." },
    [25316] = { en = "A powerful prayer that heals the target and their party for $s1. Party members must be within $a1 yards of target.", description = "Una preghiera potente cura il bersaglio e i membri del suo gruppo di $s1. I membri del gruppo devono trovarsi entro $a1 metri dal bersaglio." },
    [25349] = { en = "Target takes $s1 Nature damage every $t1 seconds.", description = "Il bersaglio subisce $s1 danni da natura ogni $t1 secondi." },
