    [25916] = { en = "Gives all members of the raid or group that share the same class with the target the Greater Blessing of Might, increasing melee attack power by $s1 for $d.  Players may only have one Blessing on them per Paladin at any one time.", description = "Conferisce Benedizione della Potenza Superiore a tutti i membri del gruppo o del raid della stessa classe del bersaglio, aumentando di $s1 la potenza d'attacco in mischia per $d.  Ogni paladino può avere attiva su un giocatore una sola Benedizione alla volta." },
    [25918] = { en = "Gives all members of the raid or group that share the same class with the target the Greater Blessing of Wisdom, restoring $s1 mana every $t1 seconds for $d.  Players may only have one Blessing on them per Paladin at any one time.", description = "Conferisce Benedizione della Saggezza Superiore a tutti i membri del gruppo o del raid della stessa classe del bersaglio, ripristinando $s1 mana ogni $t1 s per $d.  Ogni paladino può avere attiva su un giocatore una sola Benedizione alla volta." },
