    [400024] = { en = "Any attack which would otherwise kill you will instead reduce you to 10% of your maximum health. In addition, all damage taken will be reduced by up to $400024s1% for $400024d.  This effect cannot occur more than once per minute.", description = "Qualsiasi attacco che dovrebbe ucciderti ti riduce invece al 10% della salute massima. Inoltre, riduce fino al $400024s1% tutti i danni subiti per $400024d. L'effetto può attivarsi al massimo una volta al minuto." },
