    [408700] = { en = "Your Ambush and Backstab hits unbalance your target, increasing the time between their melee attacks by $408699s1%, and reducing movement speed by $408699s2% for $408699d.", description = "I tuoi attacchi Imboscata e Backstab sbilanciano il bersaglio, aumentando del $408699s1% l'intervallo tra i suoi attacchi in mischia e riducendone la velocità di movimento del $408699s2% per $408699d." },
    [409337] = { en = "For the next $409324d, $409324s1% of your damage is converted to healing on up to 3 nearby party members, and $409324s2% of your healing is converted to damage on your most recent Flame Shock target.", description = "Per i prossimi $409324d, il $409324s1% dei tuoi danni si converte in cure per un massimo di 3 membri del gruppo vicini, mentre il $409324s2% delle tue cure si converte in danni contro il bersaglio più recente del tuo Shock di Fiamma." },
    [409493] = { en = "You deal $409433s3% weapon damage, refreshing the current Sting on your target and triggering an effect:\r\n\r\nSerpent Sting - Instantly deals $409493s1% of the damage done by your Serpent Sting.\r\n\r\nViper Sting - Instantly restores mana to you equal to $409494s1% of the total amount drained by your Viper Sting.\r\n\r\nScorpid Sting - Attempts to Disarm the target for $409495d. This effect cannot occur more than once per 1 minute.", description = "Infliggi danni pari al $409433s3% dei danni dell'arma, rinnovando il Pungiglione attivo sul bersaglio e attivando un effetto:\r\n\r\nSerpent Sting: infligge istantaneamente danni pari al $409493s1% dei danni inflitti dal tuo Serpent Sting.\r\n\r\nViper Sting: ripristina istantaneamente mana pari al $409494s1% del mana totale prosciugato dal tuo Viper Sting.\r\n\r\nScorpid Sting: tenta di disarmare il bersaglio per $409495d. Questo effetto può attivarsi al massimo una volta ogni minuto." },
