    [420998] = { en = "Causes $s1 Holy damage to any creature that strikes a nearby party member. Players may only have one aura on them per paladin at any one time. The aura lasts until cancelled.", description = "Infligge $s1 danni sacri a ogni creatura che colpisce un membro del gruppo vicino. Ogni paladino può avere attiva su un giocatore una sola aura alla volta. L'aura dura finché non viene annullata." },
    [421248] = { en = "The caster is surrounded by shadows.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $28377s1 Shadow damage.  Attackers can only be damaged once every few seconds.  This damage causes no threat.  $n charges.  Lasts $d.", description = "Chi lancia l'incantesimo è avvolto dalle ombre. Quando un incantesimo o un attacco in mischia o a distanza colpisce chi lancia l'incantesimo, l'attaccante subisce $28377s1 danni da ombra. Gli attaccanti possono subire danni solo una volta ogni pochi secondi. Questi danni non generano minaccia. $n cariche. Dura $d." },
