    [437311] = { en = "Begins a ritual that creates a summoning portal.  The summoning portal can be used by 2 party or raid members to summon a targeted party or raid member.  The ritual portal requires the caster and 2 additional party or raid members to complete.  In order to participate, all players must be out of combat and right-click the portal and not move until the ritual is complete.", description = "Avvia un rituale che crea un portale d'evocazione. Il portale può essere usato da 2 membri del gruppo o del raid per evocare un membro scelto. Per completare il rituale servono l'incantatore e altri 2 membri del gruppo o del raid. Per partecipare, tutti i giocatori devono essere fuori dal combattimento, fare clic destro sul portale e restare immobili fino al termine del rituale." },
    [437425] = { en = "The caster spits a lethargic poison at players, inflicting $s1 Nature damage every $t1 sec for $d. This poison reduces hit chance by $s2% and increases ability costs by $s3%.", description = "L'incantatore sputa un veleno debilitante sui giocatori, infliggendo $s1 danni da natura ogni $t1 s per $d. Il veleno riduce del $s2% la probabilità di colpire e aumenta del $s3% il costo delle abilità." },
    [437707] = { en = "Decipher the scroll with a Comprehension Charm. Who knows what magic it contains?", description = "Decifra la pergamena con un Amuleto della Comprensione. Chissà quale magia contiene." },
    [437715] = { en = "Drains $s1 health from nearby enemies, healing the caster for up to twice the amount stolen.", description = "Prosciuga $s1 salute dai nemici vicini, curando l'incantatore fino al doppio della quantità sottratta." },
