    [440651] = { en = "Each time the target takes damage they gain a Sacred Shield, absorbing $s1 damage and increasing the paladin's chance to critically hit with Flash of Light by $s2% for up to $d.  They cannot gain this effect more than once every 6 sec.  Lasts $d.\r\n", description = "Ogni volta che il bersaglio subisce danni, riceve uno Scudo Sacro che assorbe $s1 danni e aumenta del $s2% la probabilità del paladino di infliggere un colpo critico con Lampo di Luce per un massimo di $d. L'effetto non può attivarsi sul bersaglio più di una volta ogni 6 s.  Dura $d.\r\n            " },
    [442894] = { en = "Chance to hit with spells increased by $s1%. Not cumulative with other ring runes.", description = "Aumenta di $s1% la probabilità di colpire con gli incantesimi. Non si cumula con altre rune dell’anello." },
