    [444681] = { en = "Breathes molten lava at $x1 nearby enemies, instantly dealing $s1 Fire damage and reducing the target's casting speed by $s2% for $d.", description = "Sputa lava fusa contro $x1 nemici vicini, infliggendo istantaneamente $s1 danni da fuoco e riducendo del $s2% la velocità di lancio del bersaglio per $d." },
