    [447549] = { en = "The priest becomes surrounded with anti-magic energy.  Any successful spell cast against the priest will burn $19270s1 of the attacker's Mana, causing 1 Shadow damage for each point of Mana burned.  Lasts $d.", description = "Il sacerdote viene avvolto da energia antimagia.  Ogni incantesimo che lo colpisce prosciuga $19270s1 mana dall'attaccante, infliggendo 1 danno da ombra per ogni punto mana consumato.  Dura $d." },
    [447563] = { en = "Blinds the target, causing it to wander disoriented for up to $d.  Any damage caused will remove the effect.", description = "Acceca il bersaglio, facendolo vagare disorientato per un massimo di $d.  Qualsiasi danno inflitto rimuove l'effetto." },
