    [448572] = { en = "Puts the enemy target to sleep for up to $d.  Any damage caused will awaken the target.  Only one target can be asleep at a time.", description = "Addormenta il bersaglio nemico fino a $d. Qualsiasi danno subito lo risveglia. Puoi addormentare un solo bersaglio alla volta." },
    [449409] = { en = "Inspired by the Mojo of War, your size is increased and your Strength goes up by $s1 to match your new size.  Lasts $d.", description = "Ispirato dal Mojo della Guerra, aumenti di dimensioni e la tua Forza cresce di $s1 per adattarsi alla nuova stazza.  Dura $d." },
    [449414] = { en = "A sacrificial dagger, engraved with a chant for an ancient Atal'ai blood ceremony.", description = "Un pugnale sacrificale inciso con un canto per un antico rito Atal'ai del sangue." },
    [449420] = { en = "A sacrificial dagger, engraved with a chant for an ancient Atal'ai blood ceremony.", description = "Un pugnale sacrificale inciso con un canto per un antico rito Atal'ai del sangue." },
    [449668] = { en = "+$s1 Attack Power in Cat, Bear, and Dire Bear forms only.", description = "+$s1 potenza d’attacco solo in Forma Felina, Orso o Orso Ferino." },
    [449669] = { en = "Causes $s1 Holy damage to any creature that strikes a nearby party member. Players may only have one aura on them per paladin at any one time. The aura lasts until cancelled.", description = "Infligge $s1 danni sacri a ogni creatura che colpisce un membro del gruppo vicino. Ogni paladino può avere attiva su un giocatore una sola aura alla volta. L'aura dura finché non viene annullata." },
    [449925] = { en = "Reduces the mana cost of all shapeshifting by $s1%.", description = "Riduce del $s1% il costo in mana di tutte le trasformazioni." },
    [450098] = { en = "The caster smashes the ground, inflicting $s1 Physical damage to all players and knocking them back.", description = "L'incantatore colpisce il suolo, infliggendo $s1 danni fisici a tutti i giocatori e respingendoli." },
    [450108] = { en = "Allows the caster to see through the target's eyes for $d.  Will not work if the target is in another instance or on another continent.", description = "Permette all’incantatore di vedere attraverso gli occhi del bersaglio per $d. Non funziona se il bersaglio si trova in un’altra istanza o su un altro continente." },
    [450517] = { en = "+$s1 Attack Power, up to $s3 increased damage from spells, and up to $s4 increased healing from spells.", description = "+$s1 potenza d'attacco, fino a $s3 danni aggiuntivi dagli incantesimi e fino a $s4 cure aggiuntive dagli incantesimi." },
    [450576] = { en = "Your spellcasts have a $h% chance to energize you for $450554s1 mana.", description = "I tuoi incantesimi hanno una probabilità del $h% di rigenerarti $450554s1 mana." },
