    [450643] = { en = "Infects an enemy for $d., causing it to inflict $3585s1 Nature damage to its nearby allies every $t1 sec.", description = "Infetta un nemico per $d., facendogli infliggere $3585s1 danni da natura agli alleati vicini ogni $t1 s." },
    [453053] = { en = "+$s1 Attack Power in Cat, Bear, and Dire Bear forms only.", description = "+$s1 potenza d’attacco solo in Forma Felina, Orso o Orso Ferino." },
    [456195] = { en = "Increases the target's Mana regeneration by $s2% and allows $s1% of the target's Mana regeneration to continue while casting.  Lasts $d.", description = "Aumenta del $s2% la rigenerazione del mana del bersaglio e permette di mantenerne attivo durante il lancio il $s1%.  Dura $d." },
    [458371] = { en = "Reduces all damage taken by $s1% for $d.  Once protected, you cannot be targeted by Divine Shield, Divine Protection, or Blessing of Protection again for $25771d.", description = "Riduce del $s1% tutti i danni subiti per $d. Dopo aver ricevuto protezione, non puoi essere nuovamente bersaglio di Scudo Divino, Protezione Divina o Benedizione della Protezione per $25771d." },
