    [458482] = { en = "A vicious strike that deals $s2% weapon damage and causes the target to Bleed for ${$m3/100*8*$AP} Physical damage over $d.", description = "Un colpo feroce che infligge danni pari al $s2% dei danni dell’arma e fa sanguinare il bersaglio, infliggendo ${$m3/100*8*$AP} danni fisici in $d." },
