    [463171] = { en = "Causes an enemy to fixate upon the caster and increases the caster's attack speed by $s2% for $d. While the target is fixated upon the caster, the target is very reluctant to attack anything else.", description = "Costringe un nemico a concentrarsi sull’incantatore e ne aumenta la velocità d’attacco del $s2% per $d. Finché è concentrato sull’incantatore, il bersaglio è molto riluttante ad attaccare chiunque altro." },
    [463285] = { en = "Causes $s1 Arcane damage to the target.", description = "Infligge $s1 danni arcani al bersaglio." },
    [463620] = { en = "Causes $s1 Holy damage to any creature that strikes a nearby party member. Players may only have one aura on them per paladin at any one time. The aura lasts until cancelled.", description = "Infligge $s1 danni sacri a ogni creatura che colpisce un membro del gruppo vicino. Ogni paladino può avere attiva su un giocatore una sola aura alla volta. L'aura dura finché non viene annullata." },
    [463621] = { en = "Causes $s1 Holy damage to any creature that strikes a nearby party member. Players may only have one aura on them per paladin at any one time. The aura lasts until cancelled.", description = "Infligge $s1 danni sacri a ogni creatura che colpisce un membro del gruppo vicino. Ogni paladino può avere attiva su un giocatore una sola aura alla volta. L'aura dura finché non viene annullata." },
    [465352] = { en = "Banishes the target, preventing all action but making it invulnerable for up to $d.  Only one target can be banished at a time.  Only works on Demons and Elementals.", description = "Bandisce il bersaglio, impedendogli ogni azione ma rendendolo invulnerabile per un massimo di $d. Può essere bandito un solo bersaglio alla volta. Funziona solo su Demoni ed Elementali." },
    [465414] = { en = "Increases damage done by $s1 and attack speed by $s2% for $d.", description = "Aumenta di $s1 i danni inflitti e del $s2% la velocità d'attacco per $d." },
    [466219] = { en = "The caster is surrounded by shadows.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $28377s1 Shadow damage.  Attackers can only be damaged once every few seconds.  This damage causes no threat.  $n charges.  Lasts $d.", description = "Chi lancia l'incantesimo è avvolto dalle ombre. Quando un incantesimo o un attacco in mischia o a distanza colpisce chi lancia l'incantesimo, l'attaccante subisce $28377s1 danni da ombra. Gli attaccanti possono subire danni solo una volta ogni pochi secondi. Questi danni non generano minaccia. $n cariche. Dura $d." },
    [466266] = { en = "The caster is surrounded by shadows.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $28377s1 Shadow damage.  Attackers can only be damaged once every few seconds.  This damage causes no threat.  $n charges.  Lasts $d.", description = "Chi lancia l'incantesimo è avvolto dalle ombre. Quando un incantesimo o un attacco in mischia o a distanza colpisce chi lancia l'incantesimo, l'attaccante subisce $28377s1 danni da ombra. Gli attaccanti possono subire danni solo una volta ogni pochi secondi. Questi danni non generano minaccia. $n cariche. Dura $d." },
    [466269] = { en = "The caster is surrounded by shadows.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $28377s1 Shadow damage.  Attackers can only be damaged once every few seconds.  This damage causes no threat.  $n charges.  Lasts $d.", description = "Chi lancia l'incantesimo è avvolto dalle ombre. Quando un incantesimo o un attacco in mischia o a distanza colpisce chi lancia l'incantesimo, l'attaccante subisce $28377s1 danni da ombra. Gli attaccanti possono subire danni solo una volta ogni pochi secondi. Questi danni non generano minaccia. $n cariche. Dura $d." },
    [466739] = { en = "Surrounds the caster with $n balls of lightning that have $h% chance of striking melee or ranged attackers for $s1 damage. Each time the lightning shield strikes, a ball of lightning dissipates. Thus, the shield expires after $d. or after it has struck $n times.", description = "Circonda l'incantatore con $n sfere di fulmini, ciascuna con una probabilità del $h% di colpire chi attacca in mischia o a distanza, infliggendo $s1 danni. Ogni volta che lo scudo del fulmine colpisce, una sfera si dissolve. Lo scudo termina dopo $d. oppure dopo aver colpito $n volte." },
