    [469277] = { en = "Begins taming a beast to be your companion.  Your armor is reduced by $s3% while you focus on taming the beast for $d.  If you lose the beast's attention for any reason, the taming process will fail.  Once tamed, the beast will be very unhappy and disloyal.  Try feeding the pet immediately to make it happy.", description = "Inizia ad addomesticare una bestia per farne la tua compagna. Mentre ti concentri per addomesticarla, la tua armatura si riduce del $s3% per $d. Se per qualsiasi motivo perdi l’attenzione della bestia, l’addomesticamento fallisce. Una volta addomesticata, la bestia sarà molto infelice e sleale. Prova subito a darle da mangiare per renderla felice." },
    [469301] = { en = "Begins taming a beast to be your companion.  Your armor is reduced by $s3% while you focus on taming the beast for $d.  If you lose the beast's attention for any reason, the taming process will fail.  Once tamed, the beast will be very unhappy and disloyal.  Try feeding the pet immediately to make it happy.", description = "Inizia ad addomesticare una bestia per farne la tua compagna. Mentre ti concentri per addomesticarla, la tua armatura si riduce del $s3% per $d. Se per qualsiasi motivo perdi l’attenzione della bestia, l’addomesticamento fallisce. Una volta addomesticata, la bestia sarà molto infelice e sleale. Prova subito a darle da mangiare per renderla felice." },
    [469306] = { en = "Begins taming a beast to be your companion.  Your armor is reduced by $s3% while you focus on taming the beast for $d.  If you lose the beast's attention for any reason, the taming process will fail.  Once tamed, the beast will be very unhappy and disloyal.  Try feeding the pet immediately to make it happy.", description = "Inizia ad addomesticare una bestia per farne la tua compagna. Mentre ti concentri per addomesticarla, la tua armatura si riduce del $s3% per $d. Se per qualsiasi motivo perdi l’attenzione della bestia, l’addomesticamento fallisce. Una volta addomesticata, la bestia sarà molto infelice e sleale. Prova subito a darle da mangiare per renderla felice." },
