    [474146] = { en = "Decreases the magical resistances of your spell targets by $s1.", description = "Riduce di $s1 le resistenze magiche dei bersagli dei tuoi incantesimi." },
    [474148] = { en = "Increases damage done by spells and effects by up to $s1.", description = "Aumenta fino a $s1 i danni inflitti dagli incantesimi e dagli effetti." },
    [474236] = { en = "Next spell cast within $d will cast instantly.", description = "Il prossimo incantesimo lanciato entro $d sarà istantaneo." },
    [474386] = { en = "Removes all movement impairing effects and all effects which cause loss of control of your character.", description = "Rimuove tutti gli effetti che limitano il movimento e quelli che causano la perdita di controllo del personaggio." },
    [474727] = { en = "Increases healing done by up to $s1 and damage done by up to $s2 for all magical spells and effects.", description = "Aumenta fino a $s1 le cure e fino a $s2 i danni inflitti da tutti gli incantesimi ed effetti magici." },
    [1213147] = { en = "Increases healing done by magical spells and effects by up to $s1 for $d.", description = "Aumenta fino a $s1 le cure degli incantesimi e degli effetti magici per $d." },
    [1213240] = { en = "Decreases the magical resistances of your spell targets by $s1.", description = "Riduce di $s1 le resistenze magiche dei bersagli dei tuoi incantesimi." },
    [1213241] = { en = "Increases damage done by spells and effects by up to $s1.", description = "Aumenta fino a $s1 i danni inflitti dagli incantesimi e dagli effetti." },
    [1213250] = { en = "Calls down a rain of moonlight, burning all enemies in a selected area for $s1 Arcane damage every $t1 sec. for $d.", description = "Fa piovere luce lunare, bruciando tutti i nemici nell'area selezionata e infliggendo $s1 danni arcani ogni $t1 s per $d." },
    [1213268] = { en = "Places the Hunter's Mark on the target, increasing the Ranged Attack Power of all attackers against that target by $s2.  In addition, the target of this ability can always be seen by the hunter whether it stealths or turns invisible.  The target also appears on the mini-map.  Lasts for $d.", description = "Applica Hunter’s Mark al bersaglio, aumentando di $s2 la potenza d’attacco a distanza di tutti gli attaccanti contro di esso. Inoltre, il Cacciatore può sempre vedere il bersaglio, anche se entra in modalità furtiva o diventa invisibile. Il bersaglio appare anche sulla minimappa. Dura $d." },
    [1213269] = { en = "Inflicts weapon damage and $s1 additional Fire damage to an enemy and any of its nearby allies.", description = "Infligge a un nemico e ai suoi alleati vicini i danni dell'arma più $s1 danni da fuoco aggiuntivi." },
    [1213271] = { en = "Place a fire trap that will burn the first enemy to approach for $14301o1 Fire damage over $14301d.  Trap will exist for $d.  Traps can only be placed when out of combat.  Only one trap can be active at a time.", description = "Piazza una trappola di fuoco che brucia il primo nemico che vi si avvicina, infliggendo $14301o1 danni da fuoco in $14301d.  La trappola rimane per $d. Puoi piazzare trappole solo fuori dal combattimento e averne attiva una sola alla volta." },
    [1213289] = { en = "Reduces the chance for your attacks to be dodged or parried by $s1%.", description = "Riduce del $s1% la probabilità che i tuoi attacchi vengano schivati o parati." },
    [1213290] = { en = "Reduces the chance for your attacks to be dodged or parried by $s1%.", description = "Riduce del $s1% la probabilità che i tuoi attacchi vengano schivati o parati." },
    [1213465] = { en = "Shouts at an enemy, paralyzing it with terror for $d. and causing all other nearby enemies to flee in fear.", description = "Urla contro un nemico, paralizzandolo dal terrore per $d e facendo fuggire impauriti tutti gli altri nemici vicini." },
    [1213479] = { en = "Surrounds the caster with $n balls of lightning that have $h% chance of striking melee or ranged attackers for $s1 damage. Each time the lightning shield strikes, a ball of lightning dissipates. Thus, the shield expires after $d. or after it has struck $n times.", description = "Circonda l'incantatore con $n sfere di fulmini, ciascuna con una probabilità del $h% di colpire chi attacca in mischia o a distanza, infliggendo $s1 danni. Ogni volta che lo scudo del fulmine colpisce, una sfera si dissolve. Lo scudo termina dopo $d. oppure dopo aver colpito $n volte." },
    [1213830] = { en = "Increases damage and healing done by magical spells and effects by up to $s1.", description = "Aumenta fino a $s1 i danni e le cure inflitti dagli incantesimi e dagli effetti magici." },
    [1213924] = { en = "Drains $s1 mana from those in the blast radius and does 50% of the mana drained in damage to the target.  Also Silences targets in the blast for $d.", description = "Prosciuga $s1 mana da chi si trova nell'area dell'esplosione e infligge al bersaglio danni pari al 50% del mana sottratto. Inoltre, silenzia per $d i bersagli nell'area." },
    [1213971] = { en = "Increases your attack speed by $s1%.", description = "Aumenta la tua velocità d'attacco del $s1%." },
