    [1220853] = { en = "Inflicts $s2 Frost damage to nearby enemies, reducing their movement speed by $s1% for $d.", description = "Infligge $s2 danni da gelo ai nemici vicini e ne riduce la velocità di movimento del $s1% per $d." },
    [1220862] = { en = "Calls down a blizzard that lasts $d., inflicting $s1 Frost damage every $t1 sec. to all enemies in the nearby area.", description = "Evoca una bufera che dura $d., infliggendo $s1 danni da gelo ogni $t1 s a tutti i nemici nell'area circostante." },
    [1220908] = { en = "Visual of a item summoning for quest use.", description = "Effetto visivo di evocazione di un oggetto per una missione." },
    [1220938] = { en = "Deals $s1 Fire damage every $t1 sec.", description = "Infligge $s1 danni da fuoco ogni $t1 sec." },
    [1221075] = { en = "Hold up the Enchanted Torch and attempt to dispel the darkness near Karazhan Crypts.", description = "Solleva la Torcia Incantata e tenta di dissipare l'oscurità vicino alle Cripte di Karazhan." },
    [1221379] = { en = "Subjugates the target demon, up to level $m1, forcing it to do your bidding.  While subjugated, the time between the demon's attacks is increased by $s2% and its casting speed is slowed by $s3%.  Lasts up to $d.  If you repeatedly subjugate the same demon, it will become more difficult to control with each attempt.", description = "Soggioga il demone bersaglio fino al livello $m1 e lo costringe a eseguire i tuoi ordini. Mentre è soggiogato, il tempo tra i suoi attacchi aumenta del $s2% e la sua velocità di lancio degli incantesimi si riduce del $s3%. Dura fino a $d. Se soggioghi ripetutamente lo stesso demone, ogni tentativo rende più difficile controllarlo." },
    [1221416] = { en = "Exposes all hidden and invisible enemies within $a1 yards of the targeted area, and staves off magical darkness for $d.", description = "Rivela tutti i nemici nascosti e invisibili entro $a1 metri dall'area bersaglio e dissipa l'oscurità magica per $d." },
    [1221421] = { en = "Allows the caster to see through the target's eyes for $d.  Will not work if the target is in another instance or on another continent.", description = "Permette all’incantatore di vedere attraverso gli occhi del bersaglio per $d. Non funziona se il bersaglio si trova in un’altra istanza o su un altro continente." },
    [1221422] = { en = "Allows the caster to see through the target's eyes for $d.  Will not work if the target is in another instance or on another continent.", description = "Permette all’incantatore di vedere attraverso gli occhi del bersaglio per $d. Non funziona se il bersaglio si trova in un’altra istanza o su un altro continente." },
    [1222362] = { en = "Launches shadow infused orbs towards a random player that travels out and return to it's origin. Players hit are inflicted with $s1 Shadow damage", description = "Lancia sfere intrise d'ombra contro un giocatore casuale; le sfere si allontanano e poi ritornano al punto di partenza. I giocatori colpiti subiscono $s1 danni da ombra." },
    [1222393] = { en = "Increases your attack speed by $s1%.", description = "Aumenta la tua velocità d'attacco del $s1%." },
    [1222394] = { en = "Increases your attack speed by $s1%.", description = "Aumenta la tua velocità d'attacco del $s1%." },
