    [1222570] = { en = "Deals $s1 Shadow damage split between enemy targets within $a1 yards in front of the caster. ", description = "Infligge $s1 danni da ombra, suddivisi tra i nemici entro $a1 metri di fronte all'incantatore." },
    [1222688] = { en = "Causes an enemy to fixate upon the caster and increases the caster's attack speed by $s2% for $d. While the target is fixated upon the caster, the target is very reluctant to attack anything else.", description = "Costringe un nemico a concentrarsi sull’incantatore e ne aumenta la velocità d’attacco del $s2% per $d. Finché è concentrato sull’incantatore, il bersaglio è molto riluttante ad attaccare chiunque altro." },
