    [1223455] = { en = "Improves your chance to get a critical strike with spells by ${$s1}.1%.", description = "Aumenta di ${$s1}.1% la probabilità di infliggere un colpo critico con gli incantesimi." },
    [1223679] = { en = "Alters the fabric of time, suspending beneficial world effects from dragonslaying, Dire Maul, Zul'Gurub, and Felwood.", description = "Altera il tessuto del tempo, sospendendo gli effetti benefici ottenuti uccidendo draghi, a Maglio Infausto, a Zul'Gurub e a Vilbosco." },
    [1223716] = { en = "Subjugates the target demon, up to level $m1, forcing it to do your bidding.  While subjugated, the time between the demon's attacks is increased by $s2% and its casting speed is slowed by $s3%.  Lasts up to $d.  If you repeatedly subjugate the same demon, it will become more difficult to control with each attempt.", description = "Soggioga il demone bersaglio fino al livello $m1 e lo costringe a eseguire i tuoi ordini. Mentre è soggiogato, il tempo tra i suoi attacchi aumenta del $s2% e la sua velocità di lancio degli incantesimi si riduce del $s3%. Dura fino a $d. Se soggioghi ripetutamente lo stesso demone, ogni tentativo rende più difficile controllarlo." },
    [1223793] = { en = "Unlocks your potential while inside Naxxramas.  Increasing your damage by ${$m1/100}.2% and your health by ${$m2/100}.2% for each piece of Sanctified armor equipped.", description = "Sblocca il tuo potenziale all’interno di Naxxramas. Aumenta i danni del ${$m1/100}.2% e la salute del ${$m2/100}.2% per ogni pezzo d’armatura Sanctified equipaggiato." },
    [1223794] = { en = "Unlocks your potential while inside Naxxramas.  Increasing your damage by ${$m1/100}.2% and your health by ${$m2/100}.2% for each piece of Sanctified armor equipped.", description = "Sblocca il tuo potenziale all’interno di Naxxramas. Aumenta i danni del ${$m1/100}.2% e la salute del ${$m2/100}.2% per ogni pezzo d’armatura Sanctified equipaggiato." },
