    [1226038] = { en = "Reduces the cast time of your next Healing Touch, Regrowth, or Nourish by $s1%.", description = "Riduce del $s1% il tempo di lancio del tuo prossimo Tocco Curativo, Ricrescita o Nutrimento." },
    [1227421] = { en = "Inflicts $s2 Frost damage to nearby enemies, reducing their movement speed by $s1% for $d.", description = "Infligge $s2 danni da gelo ai nemici vicini e ne riduce la velocità di movimento del $s1% per $d." },
    [1227574] = { en = "Acid rain falls from above, inflicting $s1 Nature damage to players struck.", description = "Piove acido dall’alto, infliggendo $s1 danni da natura ai giocatori colpiti." },
    [1227739] = { en = "Acid rain falls from above, inflicting $s1 Nature damage to players struck.", description = "Piove acido dall’alto, infliggendo $s1 danni da natura ai giocatori colpiti." },
    [1227807] = { en = "Acid rain falls from above, inflicting $s1 Nature damage to players struck.", description = "Piove acido dall’alto, infliggendo $s1 danni da natura ai giocatori colpiti." },
    [1228049] = { en = "Burns the enemy for ${$m1*$<power>/100*$<mult>} Shadowflame damage and then an additional ${$m2*5*$<power>/100} Shadowflame damage over $d.\r\n\r\nShadowflame triggers and benefits from all effects that modify or interact with Immolate, or with Affliction, Destruction, Fire, or Shadow spells, but only one of Immolate or Shadowflame per Warlock can be active on any target. In addition, Shadowflame can trigger your Improved Shadow Bolt talent and causes it to have $426454s2 additional charges.", description = "Brucia il nemico, infliggendo ${$m1*$<power>/100*$<mult>} danni da Ombrafiamma e poi altri ${$m2*5*$<power>/100} danni da Ombrafiamma in $d.\r\n\r\nOmbrafiamma attiva e beneficia di tutti gli effetti che modificano o interagiscono con Immolate oppure con gli incantesimi di Afflizione, Demonologia, Fuoco o Ombra; tuttavia, su ciascun bersaglio un warlock può mantenere attivo Immolate oppure Ombrafiamma. Inoltre, Ombrafiamma può attivare il talento Dardo d'Ombra Migliorato e gli conferisce $426454s2 cariche aggiuntive." },
    [1228058] = { en = "Acid rain falls from above, inflicting $s1 Nature damage to players struck.", description = "Piove acido dall’alto, infliggendo $s1 danni da natura ai giocatori colpiti." },
