    [1233280] = { en = "Flip the Lucky Doubloon. On heads, the cooldown of Lucky Doubloon is refreshed, and your critical strike chance with all spells and attacks is increased by $1232052s1% for $1232052d, stacking up to $1232052u times. On tails, all stacks of Lucky Doubloon are removed. (Must be in combat.)", description = "Lancia il Lucky Doubloon. Se esce testa, il tempo di recupero del Lucky Doubloon termina e la probabilità di colpo critico di tutti gli incantesimi e gli attacchi aumenta del $1232052s1% per $1232052d, fino a $1232052u accumuli. Se esce croce, tutti gli accumuli di Lucky Doubloon vengono rimossi. (Devi essere in combattimento.)" },
    [1233344] = { en = "Gives $s1 additional armor to nearby party members for $d. Players may only have one aura on them per paladin at any one time.", description = "Fornisce $s1 armatura aggiuntiva ai membri del gruppo vicini per $d. Ogni paladino può avere una sola aura attiva su ciascun giocatore." },
