    [1235321] = { en = "Inflicts $s1 Fire damage and an additional $s2 Fire damage every $t2 sec for $d.\r\n", description = "Infligge $s1 danni da fuoco e altri $s2 danni da fuoco ogni $t2 secondi per $d.\r\n" },
    [1235322] = { en = "Imbued weapons now cause melee attacks to inflict $1230996s1 additional Fire damage.", description = "Le armi imbevute fanno ora infliggere agli attacchi in mischia $1230996s1 danni da fuoco aggiuntivi." },
    [1235328] = { en = "Decreases the Magical damage dealt by the target by $s1 for $d.", description = "Riduce di $s1 i danni magici inflitti dal bersaglio per $d." },
    [1235390] = { en = "Your next $u instances of damage from your pet's special abilities are increased by $s1%.  Lasts $d.", description = "I prossimi $u danni inflitti dalle abilità speciali del tuo famiglio aumentano del $s1%. Dura $d." },
    [1235493] = { en = "Casts a spell when you do something.", description = "Lancia un incantesimo quando esegui un'azione." },
    [1235826] = { en = "Lacerates the enemy target, making them bleed for $o1 damage over $d plus $s2% weapon damage per existing application of Lacerate on the target. Causes a high amount of threat. This effect stacks up to $u times on the same target.", description = "Lacera il bersaglio nemico, facendolo sanguinare per $o1 danni in $d, più danni pari al $s2% dei danni dell’arma per ogni applicazione di Lacerate già presente sul bersaglio. Genera molta minaccia. L’effetto si accumula fino a $u volte sullo stesso bersaglio." },
    [1235827] = { en = "Lacerates the enemy target, making them bleed for $o1 damage over $d plus $s2% weapon damage per existing application of Lacerate on the target. Causes a high amount of threat. This effect stacks up to $u times on the same target.", description = "Lacera il bersaglio nemico, facendolo sanguinare per $o1 danni in $d, più danni pari al $s2% dei danni dell’arma per ogni applicazione di Lacerate già presente sul bersaglio. Genera molta minaccia. L’effetto si accumula fino a $u volte sullo stesso bersaglio." },
    [1236159] = { en = "Smite a target for $s1 Holy damage.", description = "Colpisce il bersaglio con Punizione, infliggendo $s1 danni sacri." },
    [1236162] = { en = "Consumes the target in holy flames that cause $s1 Holy damage and an additional $s2 Holy damage every $t2 sec for $d.", description = "Avvolge il bersaglio in fiamme sacre, infliggendo $s1 danni sacri e altri $s2 danni sacri ogni $t2 sec. per $d." },
    [1236174] = { en = "Transforms an enemy into a sheep, forcing it to wander around for up to $d. While wandering, the sheep cannot attack or cast spells, but regenerates very quickly. Any damage will transform the target back into its normal form. Only one target can be polymorphed at a time. Only works on beasts, dragons, giants, humanoids, and critters.", description = "Trasforma un nemico in una pecora, costringendolo a vagare per un massimo di $d. Mentre vaga, la pecora non può attaccare né lanciare incantesimi, ma si rigenera molto rapidamente. Qualsiasi danno riporta il bersaglio alla sua forma normale. Può essere trasformato un solo bersaglio alla volta. Funziona solo su bestie, draghi, giganti, umanoidi e piccole creature." },
    [1236217] = { en = "Attaches a permanent scope to a bow or gun that increases its damage by 10.", description = "Applica permanentemente un mirino a un arco o a un fucile, aumentandone i danni di 10." },
    [1236287] = { en = "Consumes the target in holy flames that cause $s1 Holy damage and an additional $s2 Holy damage every $t2 sec for $d.", description = "Avvolge il bersaglio in fiamme sacre, infliggendo $s1 danni sacri e altri $s2 danni sacri ogni $t2 sec. per $d." },
    [1236290] = { en = "Transforms an enemy into a sheep, forcing it to wander around for up to $d. While wandering, the sheep cannot attack or cast spells, but regenerates very quickly. Any damage will transform the target back into its normal form. Only one target can be polymorphed at a time. Only works on beasts, dragons, giants, humanoids, and critters.", description = "Trasforma un nemico in una pecora, costringendolo a vagare per un massimo di $d. Mentre vaga, la pecora non può attaccare né lanciare incantesimi, ma si rigenera molto rapidamente. Qualsiasi danno riporta il bersaglio alla sua forma normale. Può essere trasformato un solo bersaglio alla volta. Funziona solo su bestie, draghi, giganti, umanoidi e piccole creature." },
    [1237064] = { en = "Attaches a permanent scope to a bow or gun that increases its chance to hit by 3%.", description = "Applica un mirino permanente a un arco o a un’arma da fuoco, aumentando del 3% la probabilità di colpire." },
    [1237155] = { en = "Acid rain falls from above, inflicting $s1 Nature damage to players struck.", description = "Piove acido dall’alto, infliggendo $s1 danni da natura ai giocatori colpiti." },
    [1237164] = { en = "Increases your spell haste by $m2% and increases damage done by your Shadow spells by up to $s1.", description = "Aumenta del $m2% la celerità degli incantesimi e fino a $s1 i danni inflitti dagli incantesimi d’ombra." },
    [1237165] = { en = "Increases your spell haste by $m2% and increases damage done by your Shadow spells by up to $s1.", description = "Aumenta del $m2% la celerità degli incantesimi e fino a $s1 i danni inflitti dagli incantesimi d’ombra." },
    [1237171] = { en = "The molten earth deals $s1 Radiant damage every $t1 second.", description = "La terra fusa infligge $s1 danni radiosi ogni $t1 secondo." },
    [1237312] = { en = "Launches a bolt of frostfire at the enemy, causing $s2 Frostfire damage, slowing movement speed by $s1% and causing an additional $o3 Frostfire damage over $d. This spell will be checked against the lower of the target's Frost and Fire resists and counts as both Frost and Fire damage.", description = "Scaglia un dardo di fuocogelo contro il nemico, infliggendo $s2 danni da fuocogelo, riducendone la velocità di movimento del $s1% e infliggendo altri $o3 danni da fuocogelo in $d. L’incantesimo usa la resistenza più bassa tra gelo e fuoco del bersaglio e conta sia come danno da gelo sia come danno da fuoco." },
    [1237313] = { en = "Launches a bolt of frostfire at the enemy, causing $s2 Frostfire damage, slowing movement speed by $s1% and causing an additional $o3 Frostfire damage over $d. This spell will be checked against the lower of the target's Frost and Fire resists and counts as both Frost and Fire damage.", description = "Scaglia un dardo di fuocogelo contro il nemico, infliggendo $s2 danni da fuocogelo, riducendone la velocità di movimento del $s1% e infliggendo altri $o3 danni da fuocogelo in $d. L’incantesimo usa la resistenza più bassa tra gelo e fuoco del bersaglio e conta sia come danno da gelo sia come danno da fuoco." },
    [1237632] = { en = "Leap atop your charger for $d, increasing movement speed by $s2%. Usable while indoors or in combat.", description = "Balza in sella al tuo destriero per $d, aumentando del $s2% la velocità di movimento. Utilizzabile al chiuso e in combattimento." },
    [1238069] = { en = "Bite the target for $s2% normal damage plus $s1.", description = "Morde il bersaglio, infliggendo danni pari al $s2% dei danni normali più $s1." },
    [1238070] = { en = "Bite the target for $s2% normal damage plus $s1.", description = "Morde il bersaglio, infliggendo danni pari al $s2% dei danni normali più $s1." },
