    [1238214] = { en = "Heals the target and their party for $o1 over $d. Party members must be within $a1 yards of target. The amount healed is applied quickly at first, and slows down as Wild Growth reaches its full duration.", description = "Cura il bersaglio e i membri del suo gruppo di $o1 in $d. I membri del gruppo devono trovarsi entro $a1 m dal bersaglio. Le cure vengono applicate rapidamente all’inizio e rallentano man mano che Wild Growth raggiunge la durata massima." },
    [1238215] = { en = "Heals the target and their party for $o1 over $d. Party members must be within $a1 yards of target. The amount healed is applied quickly at first, and slows down as Wild Growth reaches its full duration.", description = "Cura il bersaglio e i membri del suo gruppo di $o1 in $d. I membri del gruppo devono trovarsi entro $a1 m dal bersaglio. Le cure vengono applicate rapidamente all’inizio e rallentano man mano che Wild Growth raggiunge la durata massima." },
    [1238299] = { en = "You hurl molten lava at the target, dealing $s1 Fire damage. If your Flame Shock is on the target, Lava Burst deals $s2% increased damage.", description = "Scagli lava fusa contro il bersaglio, infliggendo $s1 danni da fuoco. Se il bersaglio è affetto da Flame Shock, Lava Burst infligge il $s2% di danni aggiuntivi." },
    [1238300] = { en = "You hurl molten lava at the target, dealing $s1 Fire damage. If your Flame Shock is on the target, Lava Burst deals $s2% increased damage.", description = "Scagli lava fusa contro il bersaglio, infliggendo $s1 danni da fuoco. Se il bersaglio è affetto da Flame Shock, Lava Burst infligge il $s2% di danni aggiuntivi." },
    [1238373] = { en = "You hurl molten lava at the target, dealing $s1 Fire damage. If your Flame Shock is on the target, Lava Burst deals $408490s2% increased damage.", description = "Scagli lava fusa contro il bersaglio, infliggendo $s1 danni da fuoco. Se il bersaglio è affetto da Flame Shock, Lava Burst infligge il $408490s2% di danni aggiuntivi." },
    [1238376] = { en = "You hurl molten lava at the target, dealing $s1 Fire damage. If your Flame Shock is on the target, Lava Burst deals $408490s2% increased damage.", description = "Scagli lava fusa contro il bersaglio, infliggendo $s1 danni da fuoco. Se il bersaglio è affetto da Flame Shock, Lava Burst infligge il $408490s2% di danni aggiuntivi." },
    [1238787] = { en = "Do damage divided up evenly among all affected targets", description = "Infligge danni ripartiti equamente tra tutti i bersagli colpiti." },
    [1239242] = { en = "Heals a friendly target for $s1, an additional $o2 over $d, and increases the effectiveness of your Chain Heal casts directly on that target by $s3%.", description = "Cura un bersaglio amico di $s1 e di altri $o2 in $d. Inoltre, aumenta del $s3% l’efficacia dei lanci di Chain Heal diretti a quel bersaglio." },
    [1239243] = { en = "Heals a friendly target for $s1, an additional $o2 over $d, and increases the effectiveness of your Chain Heal casts directly on that target by $s3%.", description = "Cura un bersaglio amico di $s1 e di altri $o2 in $d. Inoltre, aumenta del $s3% l’efficacia dei lanci di Chain Heal diretti a quel bersaglio." },
    [1239696] = { en = "Blasts the target with energy, dealing $s1 Arcane damage. Each time you cast Arcane Blast, the damage of all your other spells is increased by $400573s1% and the mana cost of Arcane Blast is increased by $400573s2%. Effect stacks up to $400573u times and lasts $400573d or until any other damage spell is cast.", description = "Colpisce il bersaglio con un’esplosione d’energia, infliggendo $s1 danni arcani. Ogni volta che lanci Arcane Blast, i danni di tutti gli altri tuoi incantesimi aumentano del $400573s1% e il costo in mana di Arcane Blast aumenta del $400573s2%. L’effetto si accumula fino a $400573u volte e dura $400573d o finché non lanci un altro incantesimo che infligge danni." },
    [1239697] = { en = "Blasts the target with energy, dealing $s1 Arcane damage. Each time you cast Arcane Blast, the damage of all your other spells is increased by $400573s1% and the mana cost of Arcane Blast is increased by $400573s2%. Effect stacks up to $400573u times and lasts $400573d or until any other damage spell is cast.", description = "Colpisce il bersaglio con un’esplosione d’energia, infliggendo $s1 danni arcani. Ogni volta che lanci Arcane Blast, i danni di tutti gli altri tuoi incantesimi aumentano del $400573s1% e il costo in mana di Arcane Blast aumenta del $400573s2%. L’effetto si accumula fino a $400573u volte e dura $400573d o finché non lanci un altro incantesimo che infligge danni." },
    [1239699] = { en = "Blasts the target with energy, dealing $s1 Arcane damage. Each time you cast Arcane Blast, the damage of all your other spells is increased by $400573s1% and the mana cost of Arcane Blast is increased by $400573s2%. Effect stacks up to $400573u times and lasts $400573d or until any other damage spell is cast.", description = "Colpisce il bersaglio con un’esplosione d’energia, infliggendo $s1 danni arcani. Ogni volta che lanci Arcane Blast, i danni di tutti gli altri tuoi incantesimi aumentano del $400573s1% e il costo in mana di Arcane Blast aumenta del $400573s2%. L’effetto si accumula fino a $400573u volte e dura $400573d o finché non lanci un altro incantesimo che infligge danni." },
    [1239700] = { en = "Blasts the target with energy, dealing $s1 Arcane damage. Each time you cast Arcane Blast, the damage of all your other spells is increased by $400573s1% and the mana cost of Arcane Blast is increased by $400573s2%. Effect stacks up to $400573u times and lasts $400573d or until any other damage spell is cast.", description = "Colpisce il bersaglio con un’esplosione d’energia, infliggendo $s1 danni arcani. Ogni volta che lanci Arcane Blast, i danni di tutti gli altri tuoi incantesimi aumentano del $400573s1% e il costo in mana di Arcane Blast aumenta del $400573s2%. L’effetto si accumula fino a $400573u volte e dura $400573d o finché non lanci un altro incantesimo che infligge danni." },
    [1240044] = { en = "Deals $s1 Frost damage to an enemy target. Deals $s2% increased damage to Frozen targets.", description = "Infligge $s1 danni da gelo a un nemico. Infligge il $s2% di danni aggiuntivi ai bersagli congelati." },
    [1240045] = { en = "Deals $s1 Frost damage to an enemy target. Deals $s2% increased damage to Frozen targets.", description = "Infligge $s1 danni da gelo a un nemico. Infligge il $s2% di danni aggiuntivi ai bersagli congelati." },
    [1240046] = { en = "Deals $s1 Frost damage to an enemy target. Deals $s2% increased damage to Frozen targets.", description = "Infligge $s1 danni da gelo a un nemico. Infligge il $s2% di danni aggiuntivi ai bersagli congelati." },
    [1240047] = { en = "Deals $s1 Frost damage to an enemy target. Deals $s2% increased damage to Frozen targets.", description = "Infligge $s1 danni da gelo a un nemico. Infligge il $s2% di danni aggiuntivi ai bersagli congelati." },
