    [1240826] = { en = "Places a spell on the target that heals them for ${($m1+($bh*$bc))*$<mult>} the next time they take damage or receive non-periodic healing. When the heal occurs, Prayer of Mending jumps to a party or raid member within $401880a1 yards. Jumps up to $s2 times and lasts $401877d after each jump. This spell can only be placed on one target at a time per caster.", description = "Applica un incantesimo al bersaglio che lo cura di ${($m1+($bh*$bc))*$<mult>} la prossima volta che subisce danni o riceve una cura non periodica. Quando avviene la cura, Prayer of Mending salta a un membro del gruppo o dell’incursione entro $401880a1 m. Può saltare fino a $s2 volte e dura $401877d dopo ogni salto. Ogni incantatore può applicare questo incantesimo a un solo bersaglio alla volta." },
    [1240827] = { en = "Places a spell on the target that heals them for ${($m1+($bh*$bc))*$<mult>} the next time they take damage or receive non-periodic healing. When the heal occurs, Prayer of Mending jumps to a party or raid member within $401880a1 yards. Jumps up to $s2 times and lasts $401877d after each jump. This spell can only be placed on one target at a time per caster.", description = "Applica un incantesimo al bersaglio che lo cura di ${($m1+($bh*$bc))*$<mult>} la prossima volta che subisce danni o riceve una cura non periodica. Quando avviene la cura, Prayer of Mending salta a un membro del gruppo o dell’incursione entro $401880a1 m. Può saltare fino a $s2 volte e dura $401877d dopo ogni salto. Ogni incantatore può applicare questo incantesimo a un solo bersaglio alla volta." },
    [1240848] = { en = "Places a spell on the target that heals them the next time they take damage or receive healing.  When the heal occurs, Prayer of Mending jumps to a party or raid member within $a1 yards.  Jumps up to $n times and lasts $d after each jump.  This spell can only be placed on one target at a time.", description = "Applica un incantesimo al bersaglio che lo cura la prossima volta che subisce danni o riceve una cura. Quando avviene la cura, Prayer of Mending salta a un membro del gruppo o dell’incursione entro $a1 m. Può saltare fino a $n volte e dura $d dopo ogni salto. Può essere applicato a un solo bersaglio alla volta." },
    [1240849] = { en = "Places a spell on the target that heals them the next time they take damage or receive healing.  When the heal occurs, Prayer of Mending jumps to a party or raid member within $a1 yards.  Jumps up to $n times and lasts $d after each jump.  This spell can only be placed on one target at a time.", description = "Applica un incantesimo al bersaglio che lo cura la prossima volta che subisce danni o riceve una cura. Quando avviene la cura, Prayer of Mending salta a un membro del gruppo o dell’incursione entro $a1 m. Può saltare fino a $n volte e dura $d dopo ogni salto. Può essere applicato a un solo bersaglio alla volta." },
    [1241115] = { en = "Shows the location of all nearby undead on the minimap until cancelled.   Only one type of tracking can be used at a time.", description = "Mostra sulla minimappa i non morti nelle vicinanze finché l’effetto non viene annullato. È possibile usare un solo tipo di tracciamento alla volta." },
    [1242634] = { en = "A strike that becomes active after parrying an opponent's attack. This attack deals $s2% weapon damage plus $m1 and immobilizes the target for $d. Counterattack cannot be blocked, dodged, or parried.", description = "Un contrattacco che si attiva dopo aver parato un attacco avversario. Infligge danni pari al $s2% dei danni dell’arma più $m1 e immobilizza il bersaglio per $d. Non può essere bloccato, schivato o parato." },
    [1242971] = { en = "Shadow energy slowly destroys the target, causing $o1 damage over $d. In addition, if the Unstable Affliction is dispelled it will cause ${$m1*$m3/100} damage to the dispeller and silence them for $427719d. Only one Unstable Affliction or Immolate per Warlock can be active on any one target.", description = "L’energia d’ombra distrugge lentamente il bersaglio, infliggendo $o1 danni in $d. Se Unstable Affliction viene dissolta, infligge ${$m1*$m3/100} danni a chi l’ha dissolta e lo silenzia per $427719d. Ogni stregone può mantenere attivo un solo effetto tra Unstable Affliction e Immolate su ciascun bersaglio." },
    [1242972] = { en = "Shadow energy slowly destroys the target, causing $o1 damage over $d. In addition, if the Unstable Affliction is dispelled it will cause ${$m1*$m3/100} damage to the dispeller and silence them for $427719d. Only one Unstable Affliction or Immolate per Warlock can be active on any one target.", description = "L’energia d’ombra distrugge lentamente il bersaglio, infliggendo $o1 danni in $d. Se Unstable Affliction viene dissolta, infligge ${$m1*$m3/100} danni a chi l’ha dissolta e lo silenzia per $427719d. Ogni stregone può mantenere attivo un solo effetto tra Unstable Affliction e Immolate su ciascun bersaglio." },
    [1243229] = { en = "Inflicts $S1 shadow damage to the current enemy target.", description = "Infligge $S1 danni da ombra al bersaglio nemico attuale." },
