    [1269161] = { en = "Inflicts $s1 Fire damage and stuns targets in a 3 yard radius for $d. Any damage will break the effect.", description = "Infligge $s1 danni da fuoco e stordisce i bersagli entro un raggio di 3 m per $d. Qualsiasi danno subito interrompe l’effetto." },
    [1269192] = { en = "Inflicts $s1 Fire damage and stuns targets in a 5 yard radius for $d. Any damage will break the effect.", description = "Infligge $s1 danni da fuoco e stordisce i bersagli entro un raggio di 5 m per $d. Qualsiasi danno subito interrompe l’effetto." },
