    [1286252] = { en = "Places a Blessing on the friendly target, restoring $s1 mana every $t1 seconds for $d.  Players may only have one Blessing on them per Paladin at any one time.", description = "Benedice il bersaglio amico, ripristinando $s1 mana ogni $t1 secondi per $d.  Ogni paladino può avere attiva su un giocatore una sola Benedizione alla volta." },
