    [1286257] = { en = "Power infuses all party and raid members, increasing their Spirit by $s1 for $d.", description = "Il potere pervade tutti i membri del gruppo e del raid, aumentando il loro Spirito di $s1 per $d." },
    [1286298] = { en = "Attempts to sunder the soul of a nearby enemy. When the Phantasm is dispelled it will cause damage to the dispeller and summon a Phantasm at the targets location that travels toward the caster.", description = "Tenta di lacerare l’anima di un nemico vicino. Quando il Fantasma viene dissolto, infligge danni a chi lo dissolve ed evoca un Fantasma nella posizione del bersaglio, che si dirige verso l’incantatore." },
